/* Standalone single-file HTML exports — current frames get baked in at download time */
const EXPORT_TEMPLATES = {"carousel": "<!doctype html>\n<!-- Panel Lab export \u00b7 Carousel \u00b7 self-contained, frames embedded. Drop this file anywhere or paste the body into your page. -->\n<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>Panel Carousel</title>\n<style>\n  :root{--ink:#181512;--paper:#EDE6D8;--blue:#5B84C4;--dim:#8f8779}\n  html,body{margin:0;background:var(--ink);color:var(--paper);font-family:ui-monospace,Menlo,Consolas,monospace}\n  .wrap{overflow:hidden;cursor:grab;padding:40px 0;-webkit-mask-image:linear-gradient(90deg,transparent,#000 6%,#000 94%,transparent);mask-image:linear-gradient(90deg,transparent,#000 6%,#000 94%,transparent)}\n  .track{display:flex;gap:18px;width:max-content;will-change:transform}\n  .card{width:300px;flex-shrink:0;cursor:pointer;transition:transform .25s}\n  .card:hover{transform:translateY(-8px) rotate(-.6deg)}\n  .hd{display:grid;grid-template-columns:1fr 1fr 1fr;border:1px solid rgba(237,230,216,.22);border-bottom:none;font-size:10px}\n  .hd div{padding:3px 6px;border-left:1px solid rgba(237,230,216,.22)}\n  .hd div:first-child{border-left:none}\n  .hd b{display:block;color:var(--dim);font-size:8px;font-weight:400;text-transform:uppercase}\n  .hd span{display:block;text-align:right}\n  .card img{width:100%;display:block;border:1px solid rgba(237,230,216,.22);background:var(--paper)}\n  .hint{color:var(--dim);font-size:12px;text-align:center;margin:6px 0 30px}\n  .box{position:fixed;inset:0;background:rgba(12,10,8,.9);display:grid;place-items:center;z-index:9;cursor:zoom-out;padding:24px}\n  .box img{max-width:min(720px,100%);max-height:85vh;border:1px solid rgba(237,230,216,.3)}\n  [hidden]{display:none!important}\n</style></head><body>\n<div class=\"wrap\" id=\"wrap\"><div class=\"track\" id=\"track\"></div></div>\n<p class=\"hint\">drag to scrub \u00b7 hover to hold \u00b7 click a panel to inspect</p>\n<div class=\"box\" id=\"box\" hidden><img id=\"boximg\" alt=\"\"></div>\n<script>\nconst FRAMES=__FRAMES__;\nconst track=document.getElementById('track'),wrap=document.getElementById('wrap');\nconst box=document.getElementById('box'),boximg=document.getElementById('boximg');\n[...FRAMES,...FRAMES].forEach(f=>{\n  const c=document.createElement('div');c.className='card';\n  c.innerHTML=`<div class=\"hd\"><div><b>Shot</b><span>${f.shot}</span></div><div><b>Panel</b><span>${f.panel}</span></div><div><b>Duration</b><span>${f.dur}</span></div></div><img draggable=\"false\" alt=\"Panel ${f.panel}\">`;\n  c.querySelector('img').src=f.src;\n  c.addEventListener('click',()=>{boximg.src=f.src;box.hidden=false});\n  track.appendChild(c);\n});\nbox.addEventListener('click',()=>box.hidden=true);\nlet off=0,vel=.55,drag=null,paused=false;\nconst CARD=300,GAP=18,total=FRAMES.length*(CARD+GAP);\nwrap.addEventListener('pointerdown',e=>drag={x:e.clientX,off});\naddEventListener('pointermove',e=>{if(drag)off=drag.off-(e.clientX-drag.x)});\naddEventListener('pointerup',()=>drag=null);\nwrap.addEventListener('mouseenter',()=>paused=true);\nwrap.addEventListener('mouseleave',()=>paused=false);\n(function loop(){\n  if(!drag&&!paused)off+=vel;\n  off=((off%total)+total)%total;\n  track.style.transform=`translateX(${-off}px)`;\n  requestAnimationFrame(loop);\n})();\n</script></body></html>\n", "walk": "<!doctype html>\n<!-- Panel Lab export \u00b7 WebGL Walkthrough \u00b7 self-contained except three.js from cdnjs. Frames embedded. -->\n<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>Panel Walkthrough</title>\n<style>\n  html,body{margin:0;background:#14110e;color:#EDE6D8;font-family:ui-monospace,Menlo,Consolas,monospace;overflow:hidden}\n  #c{position:fixed;inset:0;touch-action:none}\n  .ui{position:fixed;bottom:18px;left:0;right:0;display:flex;justify-content:center;gap:10px;z-index:2}\n  .ui button{background:rgba(24,21,18,.75);color:#EDE6D8;border:1px solid #5B84C4;padding:8px 18px;font:12px/1 ui-monospace,monospace;cursor:pointer;border-radius:3px;letter-spacing:.06em}\n  .hint{position:fixed;top:14px;left:0;right:0;text-align:center;color:#8f8779;font-size:12px;z-index:2}\n</style></head><body>\n<div id=\"c\"></div>\n<p class=\"hint\">W/S or scroll to walk \u00b7 drag to look \u00b7 A/D to sidestep</p>\n<div class=\"ui\"><button id=\"back\">\u25c2 back</button><button id=\"fwd\">walk \u25b8</button></div>\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js\"></script>\n<script>\nconst FRAMES=__FRAMES__;\nconst mount=document.getElementById('c');\nconst scene=new THREE.Scene();\nscene.background=new THREE.Color(0x14110e);\nscene.fog=new THREE.Fog(0x14110e,6,34);\nconst camera=new THREE.PerspectiveCamera(62,innerWidth/innerHeight,.1,100);\ncamera.position.set(0,1.6,4);\nconst renderer=new THREE.WebGLRenderer({antialias:true});\nrenderer.setSize(innerWidth,innerHeight);\nrenderer.setPixelRatio(Math.min(2,devicePixelRatio));\nmount.appendChild(renderer.domElement);\nscene.add(new THREE.AmbientLight(0xfff2dd,.55));\nconst key=new THREE.DirectionalLight(0xffe8c8,.5);key.position.set(2,6,2);scene.add(key);\nscene.add(new THREE.GridHelper(200,100,0x3a332b,0x262019));\nconst loader=new THREE.TextureLoader();\nFRAMES.forEach((f,i)=>{\n  loader.load(f.src,tex=>{\n    const ar=tex.image.width/tex.image.height,w=4,h=w/ar;\n    const mesh=new THREE.Mesh(new THREE.PlaneGeometry(w,h),new THREE.MeshBasicMaterial({map:tex}));\n    const side=i%2===0?-1:1;\n    mesh.position.set(side*3.4,1.9,-i*5.5);\n    mesh.rotation.y=side*-.42;\n    scene.add(mesh);\n    const mat=new THREE.Mesh(new THREE.PlaneGeometry(w+.3,h+.3),new THREE.MeshBasicMaterial({color:0xede6d8}));\n    mat.position.copy(mesh.position);mat.rotation.copy(mesh.rotation);mat.translateZ(-.02);\n    scene.add(mat);\n    const glow=new THREE.PointLight(0xffedd0,.35,7);\n    glow.position.copy(mesh.position).add(new THREE.Vector3(0,.4,1.2));\n    scene.add(glow);\n  });\n});\nlet yaw=0,pitch=0,drag=null;const keys={};\nrenderer.domElement.addEventListener('pointerdown',e=>drag={x:e.clientX,y:e.clientY,yaw,pitch});\naddEventListener('pointermove',e=>{if(!drag)return;yaw=drag.yaw-(e.clientX-drag.x)*.004;pitch=Math.max(-1.1,Math.min(1.1,drag.pitch-(e.clientY-drag.y)*.004))});\naddEventListener('pointerup',()=>drag=null);\naddEventListener('keydown',e=>{keys[e.key.toLowerCase()]=true;if(['arrowup','arrowdown','w','s','a','d'].includes(e.key.toLowerCase()))e.preventDefault()});\naddEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);\naddEventListener('wheel',e=>moveZ(e.deltaY*.006),{passive:true});\nconst dir=new THREE.Vector3();\nfunction moveZ(a){dir.set(Math.sin(yaw),0,Math.cos(yaw)).multiplyScalar(-a);camera.position.add(dir)}\nfunction strafe(a){dir.set(Math.cos(yaw),0,-Math.sin(yaw)).multiplyScalar(a);camera.position.add(dir)}\nlet hold;\nfunction press(btn,amt){\n  const go=()=>moveZ(amt);\n  btn.addEventListener('pointerdown',()=>{go();hold=setInterval(go,40)});\n  btn.addEventListener('pointerup',()=>clearInterval(hold));\n  btn.addEventListener('pointerleave',()=>clearInterval(hold));\n}\npress(document.getElementById('fwd'),.14);\npress(document.getElementById('back'),-.14);\n(function loop(){\n  const sp=.09;\n  if(keys['w']||keys['arrowup'])moveZ(sp);\n  if(keys['s']||keys['arrowdown'])moveZ(-sp);\n  if(keys['a'])strafe(-sp);\n  if(keys['d'])strafe(sp);\n  camera.position.z=Math.min(6,Math.max(-FRAMES.length*5.5-4,camera.position.z));\n  camera.rotation.set(0,0,0);camera.rotateY(yaw);camera.rotateX(pitch);\n  renderer.render(scene,camera);\n  requestAnimationFrame(loop);\n})();\naddEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)});\n</script></body></html>\n", "grid": "<!doctype html>\n<!-- Panel Lab export \u00b7 Sound Grid \u00b7 self-contained, frames embedded. WebAudio, no dependencies. -->\n<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>Panel Sound Grid</title>\n<style>\n  :root{--ink:#181512;--paper:#EDE6D8;--dim:#8f8779}\n  html,body{margin:0;background:var(--ink);color:var(--paper);font-family:ui-monospace,Menlo,Consolas,monospace}\n  .grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;max-width:1100px;margin:34px auto 0;padding:0 16px}\n  @media(max-width:640px){.grid{grid-template-columns:repeat(2,1fr)}}\n  .cell{position:relative;border:1px solid rgba(237,230,216,.2);cursor:pointer;overflow:hidden;transition:transform .12s,box-shadow .15s,border-color .15s;background:transparent;padding:0}\n  .cell img{width:100%;display:block;transition:filter .15s}\n  .cell .k{position:absolute;top:6px;left:6px;width:20px;height:20px;display:grid;place-items:center;background:rgba(24,21,18,.8);color:var(--paper);font-size:11px;font-weight:600;border:1px solid rgba(237,230,216,.35);border-radius:3px}\n  .cell.on{transform:scale(.96)}\n  .hint{color:var(--dim);font-size:12px;text-align:center;margin:16px 0 34px}\n  .hint b{color:var(--paper);font-weight:600}\n</style></head><body>\n<div class=\"grid\" id=\"grid\"></div>\n<p class=\"hint\">play the board \u2014 tap panels or use keys <b>1 2 3 4 / Q W E R / A S D F</b> \u00b7 C-major pentatonic, low left \u2192 high right</p>\n<script>\nconst FRAMES=__FRAMES__;\nconst HZ=[261.63,293.66,329.63,392,440,523.25,587.33,659.25,783.99,880,1046.5,1174.66];\nconst KEYS=\"1234QWERASDF\";\nlet actx=null;\nfunction play(i,cell){\n  if(!actx)actx=new (window.AudioContext||window.webkitAudioContext)();\n  if(actx.state==='suspended')actx.resume();\n  const t=actx.currentTime,hz=HZ[i%HZ.length];\n  const o=actx.createOscillator(),o2=actx.createOscillator(),g=actx.createGain(),g2=actx.createGain();\n  o.type='triangle';o2.type='sine';o.frequency.value=hz;o2.frequency.value=hz*2;g2.gain.value=.18;\n  g.gain.setValueAtTime(.0001,t);\n  g.gain.exponentialRampToValueAtTime(.5,t+.015);\n  g.gain.exponentialRampToValueAtTime(.0001,t+.9);\n  o.connect(g);o2.connect(g2);g2.connect(g);g.connect(actx.destination);\n  o.start(t);o2.start(t);o.stop(t+1);o2.stop(t+1);\n  const hue=(i*30)%360;\n  cell.classList.add('on');\n  cell.style.borderColor=`hsl(${hue} 75% 60%)`;\n  cell.style.boxShadow=`0 0 26px hsl(${hue} 80% 55% / .55), inset 0 0 40px hsl(${hue} 80% 55% / .35)`;\n  cell.querySelector('img').style.filter=`sepia(.5) hue-rotate(${hue-40}deg) saturate(2.4)`;\n  cell.querySelector('.k').style.background=`hsl(${hue} 75% 55%)`;\n  clearTimeout(cell.__t);\n  cell.__t=setTimeout(()=>{\n    cell.classList.remove('on');\n    cell.style.borderColor='';cell.style.boxShadow='';\n    cell.querySelector('img').style.filter='';\n    cell.querySelector('.k').style.background='';\n  },450);\n}\nconst grid=document.getElementById('grid');\nconst cells=FRAMES.map((f,i)=>{\n  const c=document.createElement('button');c.className='cell';\n  c.innerHTML=`<img alt=\"Key ${KEYS[i]||''}\"><span class=\"k\">${KEYS[i]||'\u00b7'}</span>`;\n  c.querySelector('img').src=f.src;\n  c.addEventListener('pointerdown',()=>play(i,c));\n  grid.appendChild(c);\n  return c;\n});\naddEventListener('keydown',e=>{\n  const i=KEYS.indexOf(e.key.toUpperCase());\n  if(i>=0&&i<FRAMES.length)play(i,cells[i]);\n});\n</script></body></html>\n", "book": "<!doctype html>\n<!-- Panel Lab export \u00b7 3D Magazine \u00b7 self-contained, frames embedded. CSS 3D, no dependencies. -->\n<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>Panel Magazine</title>\n<style>\n  :root{--ink:#181512;--paper:#EDE6D8;--blue:#5B84C4;--dim:#8f8779}\n  html,body{margin:0;background:var(--ink);color:var(--paper);font-family:ui-monospace,Menlo,Consolas,monospace}\n  .stage{display:grid;place-items:center;padding:40px 0 22px}\n  .persp{perspective:2400px;width:min(760px,96%)}\n  .book{position:relative;width:100%;padding-bottom:38%;transform-style:preserve-3d}\n  .base{position:absolute;top:0;width:50%;height:100%;background:#e5ddcc;border:1px solid rgba(24,21,18,.35)}\n  .base.l{left:0;display:grid;place-items:center}\n  .base.r{right:0}\n  .base .spine{color:rgba(24,21,18,.4);font-size:20px;letter-spacing:.2em;text-transform:uppercase;transform:rotate(-90deg);font-family:'Arial Narrow',sans-serif}\n  .sheet{position:absolute;left:50%;top:0;width:50%;height:100%;transform-origin:left center;transition:transform .85s cubic-bezier(.35,.1,.25,1);transform-style:preserve-3d;cursor:pointer;border:1px solid rgba(24,21,18,.4)}\n  .face{position:absolute;inset:0;backface-visibility:hidden;background:var(--paper);display:flex;flex-direction:column;justify-content:center;padding:8%;box-shadow:inset 0 0 60px rgba(24,21,18,.12);box-sizing:border-box}\n  .face.back{transform:rotateY(180deg)}\n  .face .empty{color:rgba(24,21,18,.45);font-size:12px;text-align:center}\n  .hd{display:grid;grid-template-columns:1fr 1fr 1fr;border:1px solid rgba(24,21,18,.35);border-bottom:none;font-size:10px;color:#181512}\n  .hd div{padding:3px 6px;border-left:1px solid rgba(24,21,18,.35)}\n  .hd div:first-child{border-left:none}\n  .hd b{display:block;color:rgba(24,21,18,.55);font-size:8px;font-weight:400;text-transform:uppercase}\n  .hd span{display:block;text-align:right}\n  .face img{width:100%;display:block;border:1px solid rgba(24,21,18,.4)}\n  .ctrl{display:flex;justify-content:center;gap:10px;align-items:center;padding-bottom:14px}\n  .ctrl button{background:transparent;color:var(--paper);border:1px solid var(--blue);padding:7px 16px;font:12px/1 ui-monospace,monospace;cursor:pointer;border-radius:3px}\n  .ctrl button:disabled{color:var(--dim);border-color:rgba(237,230,216,.15);cursor:default}\n  .ctrl .n{color:var(--dim);font-size:12px}\n  .hint{color:var(--dim);font-size:12px;text-align:center;margin:0 0 34px}\n</style></head><body>\n<div class=\"stage\"><div class=\"persp\"><div class=\"book\" id=\"book\">\n  <div class=\"base l\"><div class=\"spine\">Storyboard</div></div>\n  <div class=\"base r\"></div>\n</div></div></div>\n<div class=\"ctrl\">\n  <button id=\"prev\">\u25c2 prev spread</button>\n  <span class=\"n\" id=\"count\"></span>\n  <button id=\"next\">next spread \u25b8</button>\n</div>\n<p class=\"hint\">click a page to turn it \u2014 two panels per spread, printed in shot order</p>\n<script>\nconst FRAMES=__FRAMES__;\nconst sheets=[];for(let i=0;i<FRAMES.length;i+=2)sheets.push([FRAMES[i],FRAMES[i+1]||null]);\nlet flipped=0;\nconst book=document.getElementById('book');\nfunction pageHTML(f){\n  if(!f)return '<div class=\"empty\">\u00b7 end of act \u00b7</div>';\n  return `<div class=\"hd\"><div><b>Shot</b><span>${f.shot}</span></div><div><b>Panel</b><span>${f.panel}</span></div><div><b>Duration</b><span>${f.dur}</span></div></div><img src=\"${f.src}\" alt=\"Panel ${f.panel}\">`;\n}\nconst els=sheets.map((pair,i)=>{\n  const s=document.createElement('div');s.className='sheet';\n  s.innerHTML=`<div class=\"face\">${pageHTML(pair[0])}</div><div class=\"face back\">${pageHTML(pair[1])}</div>`;\n  s.addEventListener('click',()=>{flipped=flipped>i?i:i+1;render()});\n  book.appendChild(s);\n  return s;\n});\nconst prev=document.getElementById('prev'),next=document.getElementById('next'),count=document.getElementById('count');\nprev.addEventListener('click',()=>{flipped=Math.max(0,flipped-1);render()});\nnext.addEventListener('click',()=>{flipped=Math.min(sheets.length,flipped+1);render()});\nfunction render(){\n  els.forEach((s,i)=>{\n    const on=flipped>i;\n    s.style.transform=`rotateY(${on?-180:0}deg)`;\n    s.style.zIndex=on?i+1:sheets.length-i+1;\n  });\n  prev.disabled=flipped===0;next.disabled=flipped===sheets.length;\n  count.textContent=`${flipped}/${sheets.length}`;\n}\nrender();\n</script></body></html>\n"};

function downloadExport(kind, frames) {
  const html = EXPORT_TEMPLATES[kind].replace("__FRAMES__", JSON.stringify(frames));
  const blob = new Blob([html], { type: "text/html" });
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob);
  a.download = `panel-${kind}.html`;
  a.click();
  setTimeout(() => URL.revokeObjectURL(a.href), 4000);
}

const INK = "#181512";
const INK2 = "#221E19";
const PAPER = "#EDE6D8";
const GRAPHITE = "#8f8779";
const BLUE = "#5B84C4"; // col-erase animation pencil blue
const RED = "#C4553E"; // red pencil

/* ---------- client-side panel detection (connected components) ---------- */
function detectPanels(img) {
  const maxW = 900;
  const scale = Math.min(1, maxW / img.naturalWidth);
  const w = Math.round(img.naturalWidth * scale);
  const h = Math.round(img.naturalHeight * scale);
  const cv = document.createElement("canvas");
  cv.width = w; cv.height = h;
  const ctx = cv.getContext("2d");
  ctx.drawImage(img, 0, 0, w, h);
  const data = ctx.getImageData(0, 0, w, h).data;
  const lum = new Float32Array(w * h);
  let sum = 0;
  for (let i = 0; i < w * h; i++) {
    const j = i * 4;
    const L = 0.299 * data[j] + 0.587 * data[j + 1] + 0.114 * data[j + 2];
    lum[i] = L; sum += L;
  }
  const mean = sum / (w * h);
  const dark = new Uint8Array(w * h);
  for (let i = 0; i < w * h; i++) dark[i] = lum[i] < mean - 28 ? 1 : 0;

  const labels = new Int32Array(w * h).fill(-1);
  const boxes = [];
  const stack = [];
  let lab = 0;
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const idx = y * w + x;
      if (!dark[idx] || labels[idx] >= 0) continue;
      let minx = x, maxx = x, miny = y, maxy = y, count = 0;
      stack.length = 0;
      stack.push(idx); labels[idx] = lab;
      while (stack.length) {
        const p = stack.pop(); count++;
        const px = p % w, py = (p / w) | 0;
        if (px < minx) minx = px; if (px > maxx) maxx = px;
        if (py < miny) miny = py; if (py > maxy) maxy = py;
        for (let dy = -1; dy <= 1; dy++) for (let dx = -1; dx <= 1; dx++) {
          const nx = px + dx, ny = py + dy;
          if (nx < 0 || ny < 0 || nx >= w || ny >= h) continue;
          const n = ny * w + nx;
          if (dark[n] && labels[n] < 0) { labels[n] = lab; stack.push(n); }
        }
      }
      boxes.push({ x: minx, y: miny, w: maxx - minx + 1, h: maxy - miny + 1, count });
      lab++;
    }
  }
  const pageA = w * h;
  const cands = boxes.filter(b => {
    const a = b.w * b.h, ar = b.w / b.h;
    return a > pageA * 0.004 && a < pageA * 0.3 && ar > 1.02 && ar < 2.6;
  }).sort((a, b) => b.w * b.h - a.w * a.h);
  const kept = [];
  for (const b of cands) {
    const cx = b.x + b.w / 2, cy = b.y + b.h / 2;
    if (kept.some(k => cx > k.x - 8 && cx < k.x + k.w + 8 && cy > k.y - 8 && cy < k.y + k.h + 8)) continue;
    kept.push(b);
  }
  if (!kept.length) return { boxes: [], scale };
  const rowH = Math.max(...kept.map(k => k.h));
  kept.sort((a, b) =>
    (Math.round(a.y / (rowH * 0.8)) - Math.round(b.y / (rowH * 0.8))) || (a.x - b.x));
  return { boxes: kept, scale };
}

function cropFrames(img, boxes, scale) {
  const out = [];
  boxes.forEach((b, i) => {
    const sx = b.x / scale, sy = b.y / scale, sw = b.w / scale, sh = b.h / scale;
    const inset = Math.min(sw, sh) * 0.03;
    const cw = sw - inset * 2, ch = sh - inset * 2;
    const tw = Math.min(512, Math.round(cw));
    const th = Math.round(ch * tw / cw);
    const cv = document.createElement("canvas");
    cv.width = tw; cv.height = th;
    cv.getContext("2d").drawImage(img, sx + inset, sy + inset, cw, ch, 0, 0, tw, th);
    out.push({ src: cv.toDataURL("image/jpeg", 0.78), panel: `${i + 1}/${boxes.length}`, dur: "—", shot: "UPLOAD" });
  });
  return out;
}

function sliceGrid(img, rows, cols) {
  const out = [];
  const cw = img.naturalWidth / cols, ch = img.naturalHeight / rows;
  for (let r = 0; r < rows; r++) for (let c = 0; c < cols; c++) {
    const tw = Math.min(512, Math.round(cw));
    const th = Math.round(ch * tw / cw);
    const cv = document.createElement("canvas");
    cv.width = tw; cv.height = th;
    cv.getContext("2d").drawImage(img, c * cw, r * ch, cw, ch, 0, 0, tw, th);
    out.push({ src: cv.toDataURL("image/jpeg", 0.78), panel: `${r * cols + c + 1}/${rows * cols}`, dur: "—", shot: "GRID" });
  }
  return out;
}

/* ---------- shared frame header (mimics the Toon Boom sheet cells) ---------- */
function FrameHeader({ f, i, light }) {
  const bd = light ? "rgba(24,21,18,.35)" : "rgba(237,230,216,.22)";
  const fg = light ? INK : PAPER;
  const dim = light ? "rgba(24,21,18,.55)" : GRAPHITE;
  return (
    <div style={{
      display: "grid", gridTemplateColumns: "1fr 1fr 1fr",
      border: `1px solid ${bd}`, borderBottom: "none",
      fontFamily: "'IBM Plex Mono', ui-monospace, monospace",
      fontSize: 10, letterSpacing: ".04em", color: fg,
    }}>
      {[["Shot", f.shot], ["Panel", f.panel], ["Duration", f.dur]].map(([k, v], j) => (
        <div key={k} style={{ borderLeft: j ? `1px solid ${bd}` : "none", padding: "3px 6px" }}>
          <div style={{ color: dim, fontSize: 8, textTransform: "uppercase" }}>{k}</div>
          <div style={{ textAlign: "right" }}>{v}</div>
        </div>
      ))}
    </div>
  );
}

/* ============================ 1 · CAROUSEL ============================ */
function Carousel({ frames }) {
  const trackRef = useRef(null);
  const state = useRef({ off: 0, vel: 0.55, drag: null, paused: false });
  const [focus, setFocus] = useState(null);
  const CARD = 300, GAP = 18;

  useEffect(() => {
    let raf;
    const loop = () => {
      const s = state.current;
      if (!s.drag && !s.paused) s.off += s.vel;
      const total = frames.length * (CARD + GAP);
      if (s.off > total) s.off -= total;
      if (s.off < 0) s.off += total;
      if (trackRef.current) trackRef.current.style.transform = `translateX(${-s.off}px)`;
      raf = requestAnimationFrame(loop);
    };
    raf = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(raf);
  }, [frames]);

  const onDown = e => { state.current.drag = { x: e.clientX, off: state.current.off }; };
  const onMove = e => {
    const d = state.current.drag;
    if (d) state.current.off = d.off - (e.clientX - d.x);
  };
  const onUp = () => { state.current.drag = null; };

  return (
    <div>
      <div
        style={{ overflow: "hidden", cursor: "grab", padding: "26px 0", maskImage: "linear-gradient(90deg, transparent, #000 6%, #000 94%, transparent)", WebkitMaskImage: "linear-gradient(90deg, transparent, #000 6%, #000 94%, transparent)" }}
        onPointerDown={onDown} onPointerMove={onMove} onPointerUp={onUp} onPointerLeave={onUp}
        onMouseEnter={() => (state.current.paused = true)}
        onMouseLeave={() => (state.current.paused = false)}
      >
        <div ref={trackRef} style={{ display: "flex", gap: GAP, width: "max-content", willChange: "transform" }}>
          {[...frames, ...frames].map((f, i) => (
            <div key={i}
              onClick={() => setFocus(f)}
              style={{ width: CARD, flexShrink: 0, transition: "transform .25s", cursor: "pointer" }}
              onMouseEnter={e => (e.currentTarget.style.transform = "translateY(-8px) rotate(-.6deg)")}
              onMouseLeave={e => (e.currentTarget.style.transform = "none")}
            >
              <FrameHeader f={f} i={i} />
              <img src={f.src} alt={`Panel ${f.panel}`} draggable={false}
                style={{ width: "100%", display: "block", border: "1px solid rgba(237,230,216,.22)", background: PAPER }} />
            </div>
          ))}
        </div>
      </div>
      <p style={{ color: GRAPHITE, fontSize: 12, fontFamily: "'IBM Plex Mono', monospace", textAlign: "center" }}>
        drag to scrub · hover to hold · click a panel to inspect
      </p>
      {focus && (
        <div onClick={() => setFocus(null)}
          style={{ position: "fixed", inset: 0, background: "rgba(12,10,8,.88)", display: "grid", placeItems: "center", zIndex: 60, cursor: "zoom-out", padding: 24 }}>
          <div style={{ maxWidth: 720, width: "100%" }}>
            <FrameHeader f={focus} />
            <img src={focus.src} alt="" style={{ width: "100%", display: "block", border: "1px solid rgba(237,230,216,.3)" }} />
          </div>
        </div>
      )}
    </div>
  );
}

/* ============================ 2 · WALKTHROUGH ============================ */
function Walkthrough({ frames }) {
  const mountRef = useRef(null);
  const keys = useRef({});

  useEffect(() => {
    const mount = mountRef.current;
    if (!mount) return;
    const W = mount.clientWidth, H = mount.clientHeight;

    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x14110e);
    scene.fog = new THREE.Fog(0x14110e, 6, 34);

    const camera = new THREE.PerspectiveCamera(62, W / H, 0.1, 100);
    camera.position.set(0, 1.6, 4);

    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(W, H);
    renderer.setPixelRatio(Math.min(2, window.devicePixelRatio));
    mount.appendChild(renderer.domElement);

    scene.add(new THREE.AmbientLight(0xfff2dd, 0.55));
    const key = new THREE.DirectionalLight(0xffe8c8, 0.5);
    key.position.set(2, 6, 2);
    scene.add(key);

    const grid = new THREE.GridHelper(200, 100, 0x3a332b, 0x262019);
    scene.add(grid);

    const loader = new THREE.TextureLoader();
    const disposables = [];
    frames.forEach((f, i) => {
      loader.load(f.src, tex => {
        const ar = tex.image.width / tex.image.height;
        const w = 4, h = w / ar;
        const geo = new THREE.PlaneGeometry(w, h);
        const mat = new THREE.MeshBasicMaterial({ map: tex });
        const mesh = new THREE.Mesh(geo, mat);
        const side = i % 2 === 0 ? -1 : 1;
        mesh.position.set(side * 3.4, 1.9, -i * 5.5);
        mesh.rotation.y = side * -0.42;
        scene.add(mesh);
        // paper mat behind
        const matGeo = new THREE.PlaneGeometry(w + 0.3, h + 0.3);
        const matMesh = new THREE.Mesh(matGeo, new THREE.MeshBasicMaterial({ color: 0xede6d8 }));
        matMesh.position.copy(mesh.position);
        matMesh.rotation.copy(mesh.rotation);
        matMesh.translateZ(-0.02);
        scene.add(matMesh);
        const glow = new THREE.PointLight(0xffedd0, 0.35, 7);
        glow.position.copy(mesh.position).add(new THREE.Vector3(0, 0.4, 1.2));
        scene.add(glow);
        disposables.push(geo, mat, tex, matGeo, matMesh.material);
      });
    });

    let yaw = 0, pitch = 0, drag = null;
    const onDown = e => { drag = { x: e.clientX, y: e.clientY, yaw, pitch }; };
    const onMove = e => {
      if (!drag) return;
      yaw = drag.yaw - (e.clientX - drag.x) * 0.004;
      pitch = Math.max(-1.1, Math.min(1.1, drag.pitch - (e.clientY - drag.y) * 0.004));
    };
    const onUp = () => { drag = null; };
    const onKey = down => e => {
      keys.current[e.key.toLowerCase()] = down;
      if (["arrowup", "arrowdown", "w", "s", "a", "d"].includes(e.key.toLowerCase())) e.preventDefault();
    };
    const kd = onKey(true), ku = onKey(false);
    const onWheel = e => { moveZ(e.deltaY * 0.006); };
    renderer.domElement.addEventListener("pointerdown", onDown);
    window.addEventListener("pointermove", onMove);
    window.addEventListener("pointerup", onUp);
    window.addEventListener("keydown", kd);
    window.addEventListener("keyup", ku);
    renderer.domElement.addEventListener("wheel", onWheel, { passive: true });

    const dir = new THREE.Vector3();
    function moveZ(amt) {
      dir.set(Math.sin(yaw), 0, Math.cos(yaw)).multiplyScalar(-amt);
      camera.position.add(dir);
    }
    function strafe(amt) {
      dir.set(Math.cos(yaw), 0, -Math.sin(yaw)).multiplyScalar(amt);
      camera.position.add(dir);
    }

    mount.__move = moveZ; // for on-screen buttons

    let raf;
    const loop = () => {
      const k = keys.current;
      const sp = 0.09;
      if (k["w"] || k["arrowup"]) moveZ(sp);
      if (k["s"] || k["arrowdown"]) moveZ(-sp);
      if (k["a"]) strafe(-sp);
      if (k["d"]) strafe(sp);
      camera.position.z = Math.min(6, Math.max(-frames.length * 5.5 - 4, camera.position.z));
      camera.rotation.set(0, 0, 0);
      camera.rotateY(yaw);
      camera.rotateX(pitch);
      renderer.render(scene, camera);
      raf = requestAnimationFrame(loop);
    };
    raf = requestAnimationFrame(loop);

    const onResize = () => {
      const w = mount.clientWidth, h = mount.clientHeight;
      camera.aspect = w / h; camera.updateProjectionMatrix();
      renderer.setSize(w, h);
    };
    window.addEventListener("resize", onResize);

    return () => {
      cancelAnimationFrame(raf);
      window.removeEventListener("pointermove", onMove);
      window.removeEventListener("pointerup", onUp);
      window.removeEventListener("keydown", kd);
      window.removeEventListener("keyup", ku);
      window.removeEventListener("resize", onResize);
      disposables.forEach(d => d.dispose && d.dispose());
      renderer.dispose();
      mount.removeChild(renderer.domElement);
    };
  }, [frames]);

  const hold = useRef(null);
  const press = amt => {
    const mv = () => mountRef.current && mountRef.current.__move && mountRef.current.__move(amt);
    mv();
    hold.current = setInterval(mv, 40);
  };
  const release = () => clearInterval(hold.current);

  return (
    <div style={{ position: "relative" }}>
      <div ref={mountRef} style={{ height: "min(62vh, 560px)", borderRadius: 4, overflow: "hidden", border: "1px solid rgba(237,230,216,.18)", touchAction: "none" }} />
      <div style={{ position: "absolute", bottom: 14, left: 0, right: 0, display: "flex", justifyContent: "center", gap: 10 }}>
        {[["◂ back", -0.14], ["walk ▸", 0.14]].map(([label, amt]) => (
          <button key={label}
            onPointerDown={() => press(amt)} onPointerUp={release} onPointerLeave={release}
            style={{ background: "rgba(24,21,18,.75)", color: PAPER, border: `1px solid ${BLUE}`, padding: "8px 18px", fontFamily: "'IBM Plex Mono', monospace", fontSize: 12, cursor: "pointer", borderRadius: 3, letterSpacing: ".06em" }}>
            {label}
          </button>
        ))}
      </div>
      <p style={{ color: GRAPHITE, fontSize: 12, fontFamily: "'IBM Plex Mono', monospace", textAlign: "center", marginTop: 10 }}>
        W/S or scroll to walk · drag to look · A/D to sidestep — panels hang in shot order down the corridor
      </p>
    </div>
  );
}

/* ============================ 3 · REACTIVE GRID ============================ */
const SCALE_HZ = [261.63, 293.66, 329.63, 392.0, 440.0, 523.25, 587.33, 659.25, 783.99, 880.0, 1046.5, 1174.66];
const KEY_ROWS = ["1234", "QWER", "ASDF"];

function ReactiveGrid({ frames }) {
  const audioRef = useRef(null);
  const [lit, setLit] = useState({});

  const play = useCallback(i => {
    if (!audioRef.current) audioRef.current = new (window.AudioContext || window.webkitAudioContext)();
    const ctx = audioRef.current;
    if (ctx.state === "suspended") ctx.resume();
    const t = ctx.currentTime;
    const osc = ctx.createOscillator();
    const osc2 = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = "triangle";
    osc2.type = "sine";
    const hz = SCALE_HZ[i % SCALE_HZ.length];
    osc.frequency.value = hz;
    osc2.frequency.value = hz * 2;
    const g2 = ctx.createGain(); g2.gain.value = 0.18;
    gain.gain.setValueAtTime(0.0001, t);
    gain.gain.exponentialRampToValueAtTime(0.5, t + 0.015);
    gain.gain.exponentialRampToValueAtTime(0.0001, t + 0.9);
    osc.connect(gain); osc2.connect(g2); g2.connect(gain);
    gain.connect(ctx.destination);
    osc.start(t); osc2.start(t);
    osc.stop(t + 1); osc2.stop(t + 1);
    setLit(l => ({ ...l, [i]: Date.now() }));
    setTimeout(() => setLit(l => { const c = { ...l }; delete c[i]; return c; }), 450);
  }, []);

  useEffect(() => {
    const onKey = e => {
      const flat = KEY_ROWS.join("");
      const idx = flat.indexOf(e.key.toUpperCase());
      if (idx >= 0 && idx < frames.length) play(idx);
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [frames, play]);

  const cols = frames.length % 4 === 0 ? 4 : Math.ceil(Math.sqrt(frames.length));

  return (
    <div>
      <div style={{ display: "grid", gridTemplateColumns: `repeat(${cols}, 1fr)`, gap: 12 }}>
        {frames.map((f, i) => {
          const hue = (i * 30) % 360;
          const on = lit[i];
          const keyLabel = KEY_ROWS.join("")[i] || "·";
          return (
            <button key={i} onPointerDown={() => play(i)}
              style={{
                position: "relative", padding: 0, border: "none", cursor: "pointer",
                background: "transparent", textAlign: "left",
                transform: on ? "scale(.96)" : "scale(1)",
                transition: "transform .12s",
              }}>
              <div style={{
                position: "relative", overflow: "hidden",
                border: `1px solid ${on ? `hsl(${hue} 75% 60%)` : "rgba(237,230,216,.2)"}`,
                boxShadow: on ? `0 0 26px hsl(${hue} 80% 55% / .55), inset 0 0 40px hsl(${hue} 80% 55% / .35)` : "none",
                transition: "box-shadow .15s, border-color .15s",
              }}>
                <img src={f.src} alt={`Key ${keyLabel}`} style={{ width: "100%", display: "block", filter: on ? `sepia(.5) hue-rotate(${hue - 40}deg) saturate(2.4)` : "none", transition: "filter .15s" }} />
                <span style={{
                  position: "absolute", top: 6, left: 6, width: 20, height: 20,
                  display: "grid", placeItems: "center",
                  background: on ? `hsl(${hue} 75% 55%)` : "rgba(24,21,18,.8)",
                  color: PAPER, fontFamily: "'IBM Plex Mono', monospace", fontSize: 11, fontWeight: 600,
                  border: "1px solid rgba(237,230,216,.35)", borderRadius: 3,
                }}>{keyLabel}</span>
              </div>
            </button>
          );
        })}
      </div>
      <p style={{ color: GRAPHITE, fontSize: 12, fontFamily: "'IBM Plex Mono', monospace", textAlign: "center", marginTop: 14 }}>
        play the board — tap panels or use keys <span style={{ color: PAPER }}>1 2 3 4 / Q W E R / A S D F</span> · C-major pentatonic, low left → high right
      </p>
    </div>
  );
}

/* ============================ 4 · MAGAZINE ============================ */
function Magazine({ frames }) {
  const sheets = useMemo(() => {
    const s = [];
    for (let i = 0; i < frames.length; i += 2) s.push([frames[i], frames[i + 1] || null]);
    return s;
  }, [frames]);
  const [flipped, setFlipped] = useState(0);

  const Page = ({ f, backLabel }) => (
    <div style={{ position: "absolute", inset: 0, background: PAPER, display: "flex", flexDirection: "column", justifyContent: "center", padding: "8%", boxShadow: "inset 0 0 60px rgba(24,21,18,.12)" }}>
      {f ? (
        <>
          <FrameHeader f={f} light />
          <img src={f.src} alt={`Panel ${f.panel}`} style={{ width: "100%", display: "block", border: "1px solid rgba(24,21,18,.4)" }} />
        </>
      ) : (
        <div style={{ color: "rgba(24,21,18,.45)", fontFamily: "'IBM Plex Mono', monospace", fontSize: 12, textAlign: "center" }}>{backLabel || "· end of act ·"}</div>
      )}
    </div>
  );

  return (
    <div>
      <div style={{ display: "grid", placeItems: "center", padding: "10px 0 22px" }}>
        <div style={{ perspective: 2400, width: "min(760px, 96%)" }}>
          <div style={{ position: "relative", width: "100%", paddingBottom: "38%", transformStyle: "preserve-3d" }}>
            {/* static left base under everything */}
            <div style={{ position: "absolute", left: 0, top: 0, width: "50%", height: "100%", background: "#e5ddcc", border: "1px solid rgba(24,21,18,.35)", display: "grid", placeItems: "center" }}>
              <div style={{ color: "rgba(24,21,18,.4)", fontFamily: "'Oswald', sans-serif", fontSize: 20, letterSpacing: ".2em", textTransform: "uppercase", transform: "rotate(-90deg)" }}>Catedral</div>
            </div>
            <div style={{ position: "absolute", right: 0, top: 0, width: "50%", height: "100%", background: "#e5ddcc", border: "1px solid rgba(24,21,18,.35)" }} />
            {sheets.map((pair, i) => {
              const isFlipped = flipped > i;
              return (
                <div key={i}
                  onClick={() => setFlipped(f => (isFlipped ? i : i + 1))}
                  style={{
                    position: "absolute", left: "50%", top: 0, width: "50%", height: "100%",
                    transformOrigin: "left center",
                    transform: `rotateY(${isFlipped ? -180 : 0}deg)`,
                    transition: "transform .85s cubic-bezier(.35,.1,.25,1)",
                    transformStyle: "preserve-3d",
                    zIndex: isFlipped ? i + 1 : sheets.length - i + 1,
                    cursor: "pointer",
                    border: "1px solid rgba(24,21,18,.4)",
                  }}>
                  <div style={{ position: "absolute", inset: 0, backfaceVisibility: "hidden" }}>
                    <Page f={pair[0]} />
                  </div>
                  <div style={{ position: "absolute", inset: 0, backfaceVisibility: "hidden", transform: "rotateY(180deg)" }}>
                    <Page f={pair[1]} />
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      </div>
      <div style={{ display: "flex", justifyContent: "center", gap: 10 }}>
        <button onClick={() => setFlipped(f => Math.max(0, f - 1))} disabled={flipped === 0}
          style={{ background: "transparent", color: flipped === 0 ? GRAPHITE : PAPER, border: `1px solid ${flipped === 0 ? "rgba(237,230,216,.15)" : BLUE}`, padding: "7px 16px", fontFamily: "'IBM Plex Mono', monospace", fontSize: 12, cursor: flipped === 0 ? "default" : "pointer", borderRadius: 3 }}>
          ◂ prev spread
        </button>
        <div style={{ alignSelf: "center", color: GRAPHITE, fontFamily: "'IBM Plex Mono', monospace", fontSize: 12 }}>
          {flipped}/{sheets.length}
        </div>
        <button onClick={() => setFlipped(f => Math.min(sheets.length, f + 1))} disabled={flipped === sheets.length}
          style={{ background: "transparent", color: flipped === sheets.length ? GRAPHITE : PAPER, border: `1px solid ${flipped === sheets.length ? "rgba(237,230,216,.15)" : BLUE}`, padding: "7px 16px", fontFamily: "'IBM Plex Mono', monospace", fontSize: 12, cursor: flipped === sheets.length ? "default" : "pointer", borderRadius: 3 }}>
          next spread ▸
        </button>
      </div>
      <p style={{ color: GRAPHITE, fontSize: 12, fontFamily: "'IBM Plex Mono', monospace", textAlign: "center", marginTop: 10 }}>
        click a page to turn it — two panels per spread, printed in shot order
      </p>
    </div>
  );
}

/* ============================ SOURCE / UPLOAD ============================ */
function SourceView({ frames, onFrames }) {
  const [preview, setPreview] = useState(null); // {img, boxes, scale, url}
  const [gridDims, setGridDims] = useState({ rows: 3, cols: 4 });
  const fileRef = useRef(null);

  const onFile = e => {
    const file = e.target.files && e.target.files[0];
    if (!file) return;
    const url = URL.createObjectURL(file);
    const img = new Image();
    img.onload = () => {
      const { boxes, scale } = detectPanels(img);
      setPreview({ img, boxes, scale, url });
    };
    img.src = url;
  };

  return (
    <div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(150px, 1fr))", gap: 10, marginBottom: 26 }}>
        {frames.map((f, i) => (
          <div key={i}>
            <FrameHeader f={f} />
            <img src={f.src} alt={`Panel ${f.panel}`} style={{ width: "100%", display: "block", border: "1px solid rgba(237,230,216,.2)" }} />
          </div>
        ))}
      </div>

      <div style={{ border: "1px dashed rgba(237,230,216,.3)", borderRadius: 4, padding: 22, textAlign: "center" }}>
        <p style={{ color: PAPER, fontFamily: "'IBM Plex Mono', monospace", fontSize: 13, margin: "0 0 12px" }}>
          Analyze a different storyboard page
        </p>
        <input ref={fileRef} type="file" accept="image/*" onChange={onFile} style={{ display: "none" }} />
        <button onClick={() => fileRef.current && fileRef.current.click()}
          style={{ background: BLUE, color: INK, border: "none", padding: "10px 22px", fontFamily: "'IBM Plex Mono', monospace", fontSize: 13, fontWeight: 600, cursor: "pointer", borderRadius: 3 }}>
          Upload page image
        </button>
        <p style={{ color: GRAPHITE, fontSize: 11, fontFamily: "'IBM Plex Mono', monospace", marginTop: 10 }}>
          Panels are found by luminance thresholding + connected-component bounding boxes, filtered by area and aspect ratio — same pass used on the Catedral sheet.
        </p>

        {preview && (
          <div style={{ marginTop: 18, textAlign: "left" }}>
            <div style={{ position: "relative", display: "inline-block", maxWidth: "100%" }}>
              <img src={preview.url} alt="Uploaded page" style={{ maxWidth: "100%", display: "block", border: "1px solid rgba(237,230,216,.25)" }} />
              {preview.boxes.map((b, i) => (
                <div key={i} style={{
                  position: "absolute",
                  left: `${(b.x / (preview.img.naturalWidth * preview.scale)) * 100}%`,
                  top: `${(b.y / (preview.img.naturalHeight * preview.scale)) * 100}%`,
                  width: `${(b.w / (preview.img.naturalWidth * preview.scale)) * 100}%`,
                  height: `${(b.h / (preview.img.naturalHeight * preview.scale)) * 100}%`,
                  border: `2px solid ${RED}`, boxShadow: "0 0 0 1px rgba(24,21,18,.5)",
                  color: RED, fontFamily: "'IBM Plex Mono', monospace", fontSize: 11, fontWeight: 600,
                }}>
                  <span style={{ background: RED, color: PAPER, padding: "0 4px" }}>{i + 1}</span>
                </div>
              ))}
            </div>
            <div style={{ display: "flex", gap: 10, flexWrap: "wrap", alignItems: "center", marginTop: 12 }}>
              <button
                disabled={!preview.boxes.length}
                onClick={() => onFrames(cropFrames(preview.img, preview.boxes, preview.scale))}
                style={{ background: preview.boxes.length ? RED : "rgba(237,230,216,.1)", color: PAPER, border: "none", padding: "9px 18px", fontFamily: "'IBM Plex Mono', monospace", fontSize: 12, fontWeight: 600, cursor: preview.boxes.length ? "pointer" : "default", borderRadius: 3 }}>
                Cut {preview.boxes.length} detected panels
              </button>
              <span style={{ color: GRAPHITE, fontFamily: "'IBM Plex Mono', monospace", fontSize: 12 }}>or slice a fixed grid:</span>
              {["rows", "cols"].map(k => (
                <label key={k} style={{ color: GRAPHITE, fontFamily: "'IBM Plex Mono', monospace", fontSize: 12 }}>
                  {k}{" "}
                  <input type="number" min={1} max={10} value={gridDims[k]}
                    onChange={e => setGridDims(d => ({ ...d, [k]: +e.target.value || 1 }))}
                    style={{ width: 44, background: INK2, color: PAPER, border: "1px solid rgba(237,230,216,.25)", fontFamily: "inherit", padding: "4px 6px", borderRadius: 3 }} />
                </label>
              ))}
              <button onClick={() => onFrames(sliceGrid(preview.img, gridDims.rows, gridDims.cols))}
                style={{ background: "transparent", color: PAPER, border: `1px solid ${BLUE}`, padding: "9px 18px", fontFamily: "'IBM Plex Mono', monospace", fontSize: 12, cursor: "pointer", borderRadius: 3 }}>
                Slice grid
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

/* ============================ SHELL ============================ */
const MODES = [
  { id: "source", shot: "SRC", label: "Frames", dur: "12" },
  { id: "carousel", shot: "OUT1", label: "Carousel", dur: "∞" },
  { id: "walk", shot: "OUT2", label: "Walkthrough", dur: "3D" },
  { id: "grid", shot: "OUT3", label: "Sound Grid", dur: "♪" },
  { id: "book", shot: "OUT4", label: "Magazine", dur: "p." },
];

export default function PanelLab() {
  const [frames, setFrames] = useState(DEMO_FRAMES);
  const [mode, setMode] = useState("source");

  return (
    <div style={{ minHeight: "100vh", background: INK, color: PAPER, padding: "0 0 60px" }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=IBM+Plex+Mono:wght@400;500;600&family=Oswald:wght@500;600&display=swap');
        * { box-sizing: border-box; }
        button:focus-visible, input:focus-visible { outline: 2px solid ${BLUE}; outline-offset: 2px; }
        @media (prefers-reduced-motion: reduce) { * { transition-duration: .01ms !important; animation: none !important; } }
      `}</style>

      <header style={{ borderBottom: "1px solid rgba(237,230,216,.15)", padding: "26px clamp(16px, 4vw, 44px) 0" }}>
        <div style={{ display: "flex", alignItems: "baseline", gap: 16, flexWrap: "wrap" }}>
          <h1 style={{ fontFamily: "'Oswald', 'Arial Narrow', sans-serif", fontWeight: 600, fontSize: "clamp(26px, 4vw, 40px)", letterSpacing: ".04em", textTransform: "uppercase", margin: 0 }}>
            Panel<span style={{ color: BLUE }}> Lab</span>
          </h1>
          <span style={{ fontFamily: "'IBM Plex Mono', monospace", fontSize: 12, color: GRAPHITE }}>
            Catedral · “The moment of truth” · ACT1 · page 2/10 · {frames.length} panels cut
          </span>
        </div>

        {/* mode switcher styled like the sheet's Shot|Panel|Duration cells */}
        <nav style={{ display: "flex", gap: 8, marginTop: 20, overflowX: "auto", paddingBottom: 0 }}>
          {MODES.map(m => {
            const on = mode === m.id;
            return (
              <button key={m.id} onClick={() => setMode(m.id)}
                style={{
                  display: "grid", gridTemplateColumns: "auto auto", gap: "0 10px",
                  background: on ? PAPER : "transparent",
                  color: on ? INK : PAPER,
                  border: "1px solid " + (on ? PAPER : "rgba(237,230,216,.3)"),
                  borderBottom: "none",
                  padding: "8px 14px 10px", cursor: "pointer",
                  fontFamily: "'IBM Plex Mono', monospace", fontSize: 12, textAlign: "left",
                  borderRadius: "4px 4px 0 0", whiteSpace: "nowrap",
                }}>
                <span style={{ fontSize: 9, color: on ? "rgba(24,21,18,.55)" : GRAPHITE, textTransform: "uppercase" }}>{m.shot}</span>
                <span style={{ fontSize: 9, color: on ? "rgba(24,21,18,.55)" : GRAPHITE, textAlign: "right" }}>{m.dur}</span>
                <span style={{ gridColumn: "1 / -1", fontWeight: 600, letterSpacing: ".03em" }}>{m.label}</span>
              </button>
            );
          })}
        </nav>
      </header>

      <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap", padding: "10px clamp(16px, 4vw, 44px)", borderBottom: "1px solid rgba(237,230,216,.1)", background: INK2 }}>
        <span style={{ fontFamily: "'IBM Plex Mono', monospace", fontSize: 11, color: GRAPHITE, letterSpacing: ".05em" }}>
          EXPORT FOR YOUR SITE ↓
        </span>
        {[["carousel", "carousel"], ["walk", "walkthrough"], ["grid", "sound-grid"], ["book", "magazine"]].map(([kind, label]) => (
          <button key={kind} onClick={() => downloadExport(kind, frames)}
            title={`Download panel-${kind}.html — standalone, current ${frames.length} frames embedded`}
            style={{ background: "transparent", color: PAPER, border: "1px solid rgba(237,230,216,.3)", padding: "5px 12px", fontFamily: "'IBM Plex Mono', monospace", fontSize: 11, cursor: "pointer", borderRadius: 3 }}
            onMouseEnter={e => (e.currentTarget.style.borderColor = BLUE)}
            onMouseLeave={e => (e.currentTarget.style.borderColor = "rgba(237,230,216,.3)")}>
            {label}.html
          </button>
        ))}
        <span style={{ fontFamily: "'IBM Plex Mono', monospace", fontSize: 11, color: GRAPHITE }}>
          self-contained files · frames baked in · no build step
        </span>
      </div>

      <main style={{ padding: "26px clamp(16px, 4vw, 44px) 0", maxWidth: 1200, margin: "0 auto" }}>
        {mode === "source" && <SourceView frames={frames} onFrames={f => { setFrames(f); }} />}
        {mode === "carousel" && <Carousel frames={frames} />}
        {mode === "walk" && <Walkthrough frames={frames} />}
        {mode === "grid" && <ReactiveGrid frames={frames} />}
        {mode === "book" && <Magazine frames={frames} />}
      </main>
    </div>
  );
}
